      {
        business_id: args.businessId,
        comment_id: commentId,
        action,
      },
    );
  } catch (e) {
    throw enhanceBusinessCommentError(e, tokenKind);
  }
}

/** Keep in sync with src/6-0-social-media-manage-comments/lib/formatTikTokCaption.ts */
export function formatTikTokCaptionForDisplay(text: string): string {
  if (!text) return "";

  return text
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\u2028/g, "\n")
    .replace(/\u2029/g, "\n\n")
    .replace(/\\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]+\n/g, "\n")
    .trim();
}

export function normalizeTikTokCaptionFromApi(caption?: string): string | undefined {
  if (!caption?.trim()) return undefined;
  return formatTikTokCaptionForDisplay(caption);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  decryptTikTokContentToken,
  encryptTikTokContentToken,
} from "./tiktokContentConfigCrypto.ts";
import {
  mergeTikTokContentOAuthScopes,
  readPlatformTikTokContentOAuth,
  readPlatformTikTokContentPublishOAuth,
  TIKTOK_CONTENT_OAUTH_SCOPES,
  TIKTOK_CONTENT_OAUTH_TOKEN_KINDS,
  type TikTokContentOAuthTokenKind,
} from "./tiktokContentAuth.ts";
import {
  refreshTikTokBusinessOrganicAccessToken,
  refreshTikTokContentAccessToken,
} from "./tiktokContentApi.ts";

export type TikTokContentAccountRow = {
  id: string;
  organization_id: string;
  open_id: string;
  label: string;
  display_name: string | null;
  avatar_url: string | null;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
};

type TokenRow = {
  access_token_enc: string;
  refresh_token_enc: string;
  access_token_expires_at: string | null;
  oauth_scopes: string | null;
  oauth_token_kind: string | null;
  publish_access_token_enc?: string | null;
  publish_refresh_token_enc?: string | null;
  publish_access_token_expires_at?: string | null;
  publish_oauth_scopes?: string | null;
};

function normalizeTokenKind(raw: string | null | undefined): TikTokContentOAuthTokenKind {
  return raw === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
    ? TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
    : TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit;
}

export async function getTikTokContentAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
): Promise<{ accessToken: string; tokenKind: TikTokContentOAuthTokenKind } | null> {
  const { data: row } = await admin
    .from("organization_tiktok_content_connection_tokens")
    .select("access_token_enc, refresh_token_enc, access_token_expires_at, oauth_scopes, oauth_token_kind")
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .maybeSingle();
  if (!row?.access_token_enc || !row?.refresh_token_enc) return null;

  const tokenRow = row as TokenRow;
  const tokenKind = normalizeTokenKind(tokenRow.oauth_token_kind);
  const expiresAtMs = tokenRow.access_token_expires_at
    ? new Date(String(tokenRow.access_token_expires_at)).getTime()
    : null;
  const needsRefresh = expiresAtMs != null &&
    Number.isFinite(expiresAtMs) &&
    expiresAtMs < Date.now() + 60_000;

  if (!needsRefresh) {
    try {
      const accessToken = await decryptTikTokContentToken(String(tokenRow.access_token_enc));
      return { accessToken, tokenKind };
    } catch (e) {
      console.error("getTikTokContentAccessToken decrypt:", e);
    }
  }

  let refreshToken: string;
  try {
    refreshToken = await decryptTikTokContentToken(String(tokenRow.refresh_token_enc));
  } catch (e) {
    console.error("getTikTokContentAccessToken refresh decrypt:", e);
    return null;
  }

  const oauth = readPlatformTikTokContentOAuth();
  const refreshed = oauth
    ? tokenKind === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser
      ? await refreshTikTokBusinessOrganicAccessToken(
        oauth.clientKey,
        oauth.clientSecret,
        refreshToken,
      )
      : await refreshTikTokContentAccessToken(oauth.clientKey, oauth.clientSecret, refreshToken)
    : null;

  if (!refreshed?.access_token) {
    try {
      const accessToken = await decryptTikTokContentToken(String(tokenRow.access_token_enc));
      return { accessToken, tokenKind };
    } catch {
      return null;
    }
  }

  try {
    const now = new Date().toISOString();
    const accessEnc = await encryptTikTokContentToken(refreshed.access_token);
    const refreshEnc = refreshed.refresh_token
      ? await encryptTikTokContentToken(refreshed.refresh_token)
      : String(tokenRow.refresh_token_enc);
    const accessExpires = refreshed.expires_in
      ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
      : tokenRow.access_token_expires_at;

    const resolvedScopes = mergeTikTokContentOAuthScopes(
      tokenRow.oauth_scopes,
      refreshed.scope,
      TIKTOK_CONTENT_OAUTH_SCOPES,
    );

    await admin.from("organization_tiktok_content_connection_tokens").update({
      access_token_enc: accessEnc,
      refresh_token_enc: refreshEnc,
      access_token_expires_at: accessExpires,
      oauth_scopes: resolvedScopes,
      updated_at: now,
    }).eq("organization_id", organizationId).eq("open_id", openId);
  } catch (e) {
    console.error("getTikTokContentAccessToken persist refresh:", e);
  }

  return { accessToken: refreshed.access_token, tokenKind };
}

export async function getTikTokPublishAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  openId: string,
): Promise<string | null> {
  const { data: row } = await admin
    .from("organization_tiktok_content_connection_tokens")
    .select(
      "access_token_enc, refresh_token_enc, access_token_expires_at, oauth_token_kind, publish_access_token_enc, publish_refresh_token_enc, publish_access_token_expires_at, publish_oauth_scopes, oauth_scopes",
    )
    .eq("organization_id", organizationId)
    .eq("open_id", openId)
    .maybeSingle();
  if (!row) return null;

  const tokenRow = row as TokenRow;
  const tokenKind = normalizeTokenKind(tokenRow.oauth_token_kind);
  const hasPublishVault = Boolean(tokenRow.publish_access_token_enc && tokenRow.publish_refresh_token_enc);

  const publishExpiresAtMs = tokenRow.publish_access_token_expires_at
    ? new Date(String(tokenRow.publish_access_token_expires_at)).getTime()
    : null;
  const publishNeedsRefresh = hasPublishVault &&
    publishExpiresAtMs != null &&
    Number.isFinite(publishExpiresAtMs) &&
    publishExpiresAtMs < Date.now() + 60_000;

  if (hasPublishVault && !publishNeedsRefresh) {
    try {
      return await decryptTikTokContentToken(String(tokenRow.publish_access_token_enc));
    } catch (e) {
      console.error("getTikTokPublishAccessToken decrypt publish:", e);
    }
  }

  if (hasPublishVault && publishNeedsRefresh) {
    const publishOAuth = readPlatformTikTokContentPublishOAuth() ?? readPlatformTikTokContentOAuth();
    if (publishOAuth) {
      try {
        const refreshToken = await decryptTikTokContentToken(
          String(tokenRow.publish_refresh_token_enc),
        );
        const refreshed = await refreshTikTokContentAccessToken(
          publishOAuth.clientKey,
          publishOAuth.clientSecret,
          refreshToken,
        );
        if (refreshed?.access_token) {
          const now = new Date().toISOString();
          const accessEnc = await encryptTikTokContentToken(refreshed.access_token);
          const refreshEnc = refreshed.refresh_token
            ? await encryptTikTokContentToken(refreshed.refresh_token)
            : String(tokenRow.publish_refresh_token_enc);
          const accessExpires = refreshed.expires_in
            ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
            : tokenRow.publish_access_token_expires_at;
          const publishScopes = mergeTikTokContentOAuthScopes(
            tokenRow.publish_oauth_scopes,
            refreshed.scope,
            TIKTOK_CONTENT_OAUTH_SCOPES,
          );
          await admin.from("organization_tiktok_content_connection_tokens").update({
            publish_access_token_enc: accessEnc,
            publish_refresh_token_enc: refreshEnc,
            publish_access_token_expires_at: accessExpires,
            publish_oauth_scopes: publishScopes,
            updated_at: now,
          }).eq("organization_id", organizationId).eq("open_id", openId);
          return refreshed.access_token;
        }
      } catch (e) {
        console.error("getTikTokPublishAccessToken refresh publish:", e);
      }
    }
    try {
      return await decryptTikTokContentToken(String(tokenRow.publish_access_token_enc));
    } catch {
      /* fall through */
    }
  }

  if (tokenKind === TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.loginKit) {
    const primary = await getTikTokContentAccessToken(admin, organizationId, openId);
    return primary?.accessToken ?? null;
  }

  return null;
}

export async function resolveOrgTikTokContentForMetrics(
  admin: SupabaseClient,
  organizationId: string,
  openIdParam?: string | null,
): Promise<{
  accessToken: string;
  account: TikTokContentAccountRow;
  tokenKind: TikTokContentOAuthTokenKind;
} | null> {
  let account: TikTokContentAccountRow | null = null;

  if (openIdParam) {
    const { data: row } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("open_id", openIdParam.trim())
      .maybeSingle();
    if (row) account = row as TikTokContentAccountRow;
  }

  if (!account) {
    const { data: defaultRow } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("is_default", true)
      .maybeSingle();
    account = (defaultRow as TikTokContentAccountRow | null) ?? null;
  }

  if (!account) {
    const { data: firstRow } = await admin
      .from("organization_tiktok_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .order("sort_order", { ascending: true })
      .limit(1)
      .maybeSingle();
    account = (firstRow as TikTokContentAccountRow | null) ?? null;
  }

  if (!account?.open_id) return null;

  const tokenResult = await getTikTokContentAccessToken(admin, organizationId, account.open_id);
  if (!tokenResult) return null;

  return {
    accessToken: tokenResult.accessToken,
    account,
    tokenKind: tokenResult.tokenKind,
  };
}

/**
 * AES-256-GCM for TikTok Content OAuth tokens.
 * Reuses TIKTOK_ADS_CONFIG_ENCRYPTION_KEY (or TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("TIKTOK_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptTikTokContentToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptTikTokContentToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}

import { readPlatformTikTokAdsOAuth, tiktokAdsOAuthRedirectUri } from "./tiktokAdsAuth.ts";
import {
  readPlatformTikTokContentOAuth,
  readPlatformTikTokContentPublishOAuth,
  tiktokContentOAuthRedirectUri,
} from "./tiktokContentAuth.ts";

/** business-api — Synkerja Content Insight (account holder: organic, comments). */
export const TIKTOK_BUSINESS_CONTENT_APP_ID = "7649637336472354817";

/** business-api — Synkerja Office (advertiser OAuth: TikTok Ads). */
export const TIKTOK_BUSINESS_ADS_APP_ID = "7649636462582366225";

/** developers.tiktok.com — Login Kit / Direct Post (open.tiktokapis.com). */
export const TIKTOK_DEVELOPERS_CONTENT_APP_ID = "7654513562417039368";

export type TikTokContentAppMatch = "business_content" | "business_ads" | "developers_content" | "unknown";
export type TikTokAdsAppMatch = "business_ads" | "business_content" | "developers_content" | "unknown";

export type TikTokCredentialSlotDiagnostic = {
  env_keys: string[];
  configured: boolean;
  client_id_masked: string | null;
  matched_app: TikTokContentAppMatch | TikTokAdsAppMatch | null;
  matched_app_label: string | null;
  oauth_redirect_uri: string | null;
  recommendation: string | null;
};

function maskClientId(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return "";
  if (trimmed.length <= 8) return `${trimmed.slice(0, 2)}…${trimmed.slice(-2)}`;
  return `${trimmed.slice(0, 4)}…${trimmed.slice(-4)}`;
}

function matchContentAppId(clientId: string): {
  matched_app: TikTokContentAppMatch;
  matched_app_label: string | null;
} {
  const id = clientId.trim();
  if (id === TIKTOK_BUSINESS_CONTENT_APP_ID) {
    return {
      matched_app: "business_content",
      matched_app_label: "Synkerja Content Insight (business-api.tiktok.com)",
    };
  }
  if (id === TIKTOK_BUSINESS_ADS_APP_ID) {
    return {
      matched_app: "business_ads",
      matched_app_label: "Synkerja Office (business-api) — seharusnya untuk TIKTOK_ADS_*, bukan CONTENT",
    };
  }
  if (id === TIKTOK_DEVELOPERS_CONTENT_APP_ID) {
    return {
      matched_app: "developers_content",
      matched_app_label: "Synckerja Office (developers.tiktok.com — Login Kit / Direct Post)",
    };
  }
  return { matched_app: "unknown", matched_app_label: null };
}

function matchAdsAppId(clientId: string): {
  matched_app: TikTokAdsAppMatch;
  matched_app_label: string | null;
} {
  const id = clientId.trim();
  if (id === TIKTOK_BUSINESS_ADS_APP_ID) {
    return {
      matched_app: "business_ads",
      matched_app_label: "Synkerja Office (business-api.tiktok.com)",
    };
  }
  if (id === TIKTOK_BUSINESS_CONTENT_APP_ID) {
    return {
      matched_app: "business_content",
      matched_app_label: "Synkerja Content Insight — seharusnya untuk TIKTOK_CONTENT_*, bukan ADS",
    };
  }
  if (id === TIKTOK_DEVELOPERS_CONTENT_APP_ID) {
    return {
      matched_app: "developers_content",
      matched_app_label: "developers.tiktok.com — bukan untuk TikTok Ads",
    };
  }
  return { matched_app: "unknown", matched_app_label: null };
}

function buildContentRecommendation(matched: TikTokContentAppMatch): string | null {
  if (matched === "business_content") {
    return "Benar untuk organic analytics & komentar. Auto-post publik tetap butuh app review di developers.tiktok.com (Login Kit).";
  }
  if (matched === "business_ads") {
    return `Salah slot — pindahkan Synkerja Office (${TIKTOK_BUSINESS_ADS_APP_ID}) ke TIKTOK_ADS_*. CONTENT harus Synkerja Content Insight (${TIKTOK_BUSINESS_CONTENT_APP_ID}).`;
  }
  if (matched === "developers_content") {
    return "Ini app developers.tiktok.com (Synckerja Office) — cocok untuk Direct Post setelah App Review + Direct Post audit. Untuk organic/komentar gunakan Synkerja Content Insight di business-api.";
  }
  if (matched === "unknown") {
    return "Client key tidak cocok dengan App ID Synckerja yang dikenal. Cek Supabase secrets vs TikTok portal.";
  }
  return null;
}

function buildAdsRecommendation(matched: TikTokAdsAppMatch): string | null {
  if (matched === "business_ads") {
    return "Benar — Synkerja Office untuk modul TikTok Ads (advertiser OAuth).";
  }
  if (matched === "business_content") {
    return `Salah slot — Synkerja Content Insight (${TIKTOK_BUSINESS_CONTENT_APP_ID}) untuk TIKTOK_CONTENT_*, bukan ADS.`;
  }
  if (matched === "developers_content") {
    return "TIKTOK_ADS harus memakai Synkerja Office di business-api.tiktok.com, bukan developers.tiktok.com.";
  }
  if (matched === "unknown") {
    return `App ID tidak dikenali — gunakan Synkerja Office (${TIKTOK_BUSINESS_ADS_APP_ID}).`;
  }
  return null;
}

function isKnownTikTokBusinessAppId(id: string): boolean {
  return id === TIKTOK_BUSINESS_CONTENT_APP_ID || id === TIKTOK_BUSINESS_ADS_APP_ID;
}

/** Login Kit client key is often an opaque string, not the numeric App ID in the portal URL. */
function looksLikeDevelopersLoginKitClientKey(clientId: string): boolean {
  const id = clientId.trim();
  if (!id || isKnownTikTokBusinessAppId(id)) return false;
  if (id === TIKTOK_DEVELOPERS_CONTENT_APP_ID) return true;
  if (/^\d{15,22}$/.test(id)) return false;
  return id.length >= 6;
}

function matchPublishAppId(clientId: string): {
  matched_app: TikTokContentAppMatch;
  matched_app_label: string | null;
} {
  const id = clientId.trim();
  if (id === TIKTOK_BUSINESS_CONTENT_APP_ID) {
    return {
      matched_app: "business_content",
      matched_app_label: "Synkerja Content Insight (business-api) — seharusnya untuk TIKTOK_CONTENT_*, bukan PUBLISH",
    };
  }
  if (id === TIKTOK_BUSINESS_ADS_APP_ID) {
    return {
      matched_app: "business_ads",
      matched_app_label: "Synkerja Office (business-api) — seharusnya untuk TIKTOK_ADS_*, bukan PUBLISH",
    };
  }
  if (id === TIKTOK_DEVELOPERS_CONTENT_APP_ID) {
    return {
      matched_app: "developers_content",
      matched_app_label: "Synckerja Office (developers.tiktok.com — Login Kit / Direct Post)",
    };
  }
  if (looksLikeDevelopersLoginKitClientKey(id)) {
    return {
      matched_app: "developers_content",
      matched_app_label: "Synckerja Office Login Kit client key (developers.tiktok.com)",
    };
  }
  return { matched_app: "unknown", matched_app_label: null };
}

function buildPublishRecommendation(matched: TikTokContentAppMatch, configured: boolean): string | null {
  if (matched === "developers_content") {
    return "Benar — Synckerja Office (developers.tiktok.com) untuk Login Kit / Direct Post (video.upload, video.publish).";
  }
  if (matched === "business_content") {
    return `Salah slot — gunakan developers app (App ID portal ${TIKTOK_DEVELOPERS_CONTENT_APP_ID}), bukan Synkerja Content Insight business-api.`;
  }
  if (matched === "business_ads") {
    return `Salah slot — ini App Synkerja Office. Publish butuh developers.tiktok.com (App ID portal ${TIKTOK_DEVELOPERS_CONTENT_APP_ID}).`;
  }
  if (matched === "unknown") {
    if (!configured) {
      return "Belum diisi — tambahkan credential developers.tiktok.com untuk authorize publish (video.upload / video.publish).";
    }
    return "Client key tidak valid — pastikan TIKTOK_CONTENT_PUBLISH_CLIENT_KEY adalah Client key dari developers.tiktok.com (bukan Client secret atau App ID business-api).";
  }
  return null;
}

export function buildTikTokCredentialDiagnostics(): {
  content: TikTokCredentialSlotDiagnostic;
  publish: TikTokCredentialSlotDiagnostic;
  ads: TikTokCredentialSlotDiagnostic;
  content_matches_ads: boolean | null;
  summary: string;
} {
  const contentOAuth = readPlatformTikTokContentOAuth();
  const publishOAuth = readPlatformTikTokContentPublishOAuth();
  const adsOAuth = readPlatformTikTokAdsOAuth();

  const contentMatch = contentOAuth
    ? matchContentAppId(contentOAuth.clientKey)
    : { matched_app: null, matched_app_label: null };

  const adsMatch = adsOAuth
    ? matchAdsAppId(adsOAuth.appId)
    : { matched_app: null, matched_app_label: null };

  const publishMatch = publishOAuth
    ? matchPublishAppId(publishOAuth.clientKey)
    : { matched_app: null, matched_app_label: null };

  const content: TikTokCredentialSlotDiagnostic = {
    env_keys: ["TIKTOK_CONTENT_CLIENT_KEY", "TIKTOK_CONTENT_CLIENT_SECRET"],
    configured: Boolean(contentOAuth),
    client_id_masked: contentOAuth ? maskClientId(contentOAuth.clientKey) : null,
    matched_app: contentMatch.matched_app,
    matched_app_label: contentMatch.matched_app_label,
    oauth_redirect_uri: contentOAuth ? tiktokContentOAuthRedirectUri() : null,
    recommendation: contentMatch.matched_app
      ? buildContentRecommendation(contentMatch.matched_app)
      : null,
  };

  const publish: TikTokCredentialSlotDiagnostic = {
    env_keys: ["TIKTOK_CONTENT_PUBLISH_CLIENT_KEY", "TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET"],
    configured: Boolean(publishOAuth),
    client_id_masked: publishOAuth ? maskClientId(publishOAuth.clientKey) : null,
    matched_app: publishMatch.matched_app,
    matched_app_label: publishMatch.matched_app_label,
    oauth_redirect_uri: tiktokContentOAuthRedirectUri(),
    recommendation: publishMatch.matched_app
      ? buildPublishRecommendation(publishMatch.matched_app, true)
      : buildPublishRecommendation("unknown", false),
  };

  const ads: TikTokCredentialSlotDiagnostic = {
    env_keys: ["TIKTOK_ADS_CLIENT_KEY", "TIKTOK_ADS_CLIENT_SECRET"],
    configured: Boolean(adsOAuth),
    client_id_masked: adsOAuth ? maskClientId(adsOAuth.appId) : null,
    matched_app: adsMatch.matched_app,
    matched_app_label: adsMatch.matched_app_label,
    oauth_redirect_uri: adsOAuth ? tiktokAdsOAuthRedirectUri() : null,
    recommendation: adsMatch.matched_app ? buildAdsRecommendation(adsMatch.matched_app) : null,
  };

  const content_matches_ads = contentOAuth && adsOAuth
    ? contentOAuth.clientKey.trim() === adsOAuth.appId.trim()
    : null;

  let summary = "Konfigurasi TikTok server belum lengkap.";
  if (content.matched_app === "business_content" && ads.matched_app === "business_ads") {
    summary = publish.matched_app === "developers_content"
      ? "OK: CONTENT (business) + PUBLISH (developers) + ADS (Synkerja Office)."
      : "CONTENT & ADS OK. Tambahkan TIKTOK_CONTENT_PUBLISH_* (developers.tiktok.com) untuk auto-post.";
  } else if (content.matched_app === "business_content") {
    summary = "TIKTOK_CONTENT OK (Synkerja Content Insight). Periksa TIKTOK_ADS (harus Synkerja Office).";
  } else if (ads.matched_app === "business_ads" && content.configured) {
    summary = "TIKTOK_ADS OK (Synkerja Office). Periksa TIKTOK_CONTENT (harus Synkerja Content Insight).";
  } else if (content.matched_app === "developers_content") {
    summary = "TIKTOK_CONTENT memakai developers.tiktok.com — tunggu App Review untuk publish publik.";
  } else if (content.configured || ads.configured) {
    summary = "Salah satu atau kedua App ID tidak cocok dengan pemetaan Synckerja yang diharapkan.";
  }

  return { content, publish, ads, content_matches_ads, summary };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const tiktokAdsCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const TIKTOK_ADS_API_VERSION = "v1.3";
export const TIKTOK_ADS_API_BASE = `https://business-api.tiktok.com/open_api/${TIKTOK_ADS_API_VERSION}`;

export function tiktokAdsJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...tiktokAdsCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformTikTokAdsOAuth(): { appId: string; appSecret: string } | null {
  const appId = Deno.env.get("TIKTOK_ADS_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_ADS_APP_ID")?.trim() ?? "";
  const appSecret = Deno.env.get("TIKTOK_ADS_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_ADS_APP_SECRET")?.trim() ?? "";
  if (!appId || !appSecret) return null;
  return { appId, appSecret };
}

export function isTikTokAdsPlatformConfigured(): boolean {
  return readPlatformTikTokAdsOAuth() !== null;
}

/** Returns 503 when platform app credentials are missing from Supabase secrets. */
export function requireTikTokAdsPlatformConfigured(): Response | null {
  if (!isTikTokAdsPlatformConfigured()) {
    return tiktokAdsJson(
      {
        error:
          "TikTok Ads is not configured on the server. Set TIKTOK_ADS_CLIENT_KEY and TIKTOK_ADS_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function tiktokAdsOAuthRedirectUri(): string {
  const explicit = Deno.env.get("TIKTOK_ADS_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/tiktok-ads-oauth-callback`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
  return raw.replace(/\/+$/, "");
}

export const TIKTOK_ADS_OAUTH_RETURN_PATHS = new Set([
  "/omnichannel/settings/offline-conversion",
  "/digital-marketing/tiktok-ads/settings",
]);

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: tiktokAdsJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: tiktokAdsJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelTikTokAdsAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOrgAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelTikTokAdsAdmin(admin, userId, organizationId);
  if (!ok) return tiktokAdsJson({ error: "Forbidden" }, 403);
  return null;
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return tiktokAdsJson({ error: "Forbidden" }, 403);
  }
  return null;
}
